  if (guests_ !== undefined) input.guests = guests_;
  if (season !== undefined) input.season = season;
  if (coupon !== undefined) input.coupon = coupon;
  if (loyaltyYears !== undefined) input.loyaltyYears = loyaltyYears;
  tested++;
  const a = orig(input), b = neu(input);
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    mismatches++;
    if (mismatches <= 20) console.log('MISMATCH', JSON.stringify(input), 'orig=', a, 'new=', b);
  } else if (a.ok && (a.line !== orig(input).line)) { console.log('line mismatch'); }
}
