export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  name: "standard" | "suite" | "villa";
  maxNights: number;
  minNights: number;
  maxGuests: number;
  basePerNight: number;
  highPerNight: number;
  perGuestExtra: number;
  flatFee: number;
}

// Shared rule across every category: privileged guests (loyalty >= 3 or VIP
// coupon) get a 10% discount and a "flex" cancellation policy.
function isPrivileged(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears >= 3 || coupon === "VIP";
}

const CATEGORIES: ReadonlyArray<CategorySpec> = [
  {
    name: "standard",
    maxNights: 14,
    minNights: 1,
    maxGuests: 2,
    basePerNight: 80,
    highPerNight: 30,
    perGuestExtra: 0,
    flatFee: 0,
  },
  {
    name: "suite",
    maxNights: 21,
    minNights: 1,
    maxGuests: 4,
    basePerNight: 150,
    highPerNight: 60,
    perGuestExtra: 25,
    flatFee: 0,
  },
  {
    name: "villa",
    maxNights: 28,
    minNights: 3,
    maxGuests: 8,
    basePerNight: 300,
    highPerNight: 120,
    perGuestExtra: 0,
    flatFee: 500,
  },
];

// Whether a privilege should ever trigger depends only on the category's
// minimum stay (the villa enforces a minimum stay error separate from the
// generic "bad nights" error).
function nightsError(spec: CategorySpec, nights: number): string | null {
  if (!Number.isInteger(nights) || nights < 1 || nights > spec.maxNights) {
    return "bad nights";
  }
  if (spec.minNights > 1 && nights < spec.minNights) {
    return "villa minimum stay";
  }
  return null;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const spec = CATEGORIES.find((c) => c.name === req.category);
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season;

  const badNights = nightsError(spec, nights);
  if (badNights) {
    return { ok: false, error: badNights };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const privileged = isPrivileged(req.loyaltyYears as number, req.coupon);

  let total =
    (spec.basePerNight + (season === "high" ? spec.highPerNight : 0)) * nights;
  if (privileged) {
    total -= Math.floor(total / 10);
  }
  if (guests > 2) {
    total += spec.perGuestExtra;
  }
  total += spec.flatFee;

  const policy = privileged ? "flex" : "strict";
  const line = `${spec.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

